	filters?: Array<BaserowConditionalColorValueProviderConfColorFilter> | null;
	/** A list of filter groups that the row must meet to get the selected color. */
	filter_groups?: Array<BaserowConditionalColorValueProviderConfColorFilterGroup> | null;
