export type BaserowSettings = {
	/** Indicates whether new users can create a new account when signing up. */
	allow_new_signups?: boolean | null;
	/** Indicates whether invited users can create an account when signing up, even if allow_new_signups is disabled. */
	allow_signups_via_workspace_invitations?: boolean | null;
	/** Indicates whether users can request a password reset link. */
	allow_reset_password?: boolean | null;
	/** Indicates whether all users can create workspaces, or just staff. */
	allow_global_workspace_creation?: boolean | null;
	/** Number of days after the last login for an account pending deletion to be deleted */
	account_deletion_grace_delay?: number | null;
	/** Indicates that there are no admin users in the database yet, so in the frontend the signup form will be shown instead of the login page. */
	show_admin_signup_page?: boolean | null;
	/** Runs a job once per day which calculates per workspace row counts and file storage usage, displayed on the admin workspace page. */
	track_workspace_usage?: boolean | null;
	/** Indicates whether the `We need your help!` message will be shown on the dashboard */
	show_baserow_help_request?: boolean | null;
	/** Co-branding logo that's placed next to the Baserow logo (176x29). */
	co_branding_logo?: BaserowUserFile | null;
	/** Controls whether user email addresses have to be verified. * `no_verification` - no_verification * `recommended` - recommended * `enforced` - enforced */
	email_verification?: (BaserowEmailVerificationEnum | BaserowNullEnum) | null;
	/** Indicates whether the signature of imported files should be verified. */
	verify_import_signature?: boolean | null;
	/** Indicates whether anonymous visitors can report publicly shared resources, like views and forms, for abuse. */
	allow_reporting_abuse?: boolean | null;
	/** Whether a user template made public, and every edit of a listed one, is listed only once an instance admin approves it. Switching it off approves the templates in review that an admin could approve, except the ones rejected since their last approval. Can only be changed with the user templates… */
	user_templates_require_approval?: boolean | null;
	/** Whether this instance is configured to receive inbound email for the automation email trigger. Derived from the instance's environment and read-only. */
	inbound_email_enabled?: boolean | null;
	/** Whether this instance is configured to deliver emails, for example invitations and email verifications. Derived from the instance's environment and read-only. */
	email_delivery_enabled?: boolean | null;
};

